SELECT url, count(*) FROM (SELECT * FROM streamed_table('/pgch_2684774_1_1_0', 'eventdate Date, counterid Int32, url String, isrefresh Int16, islink Int16, isdownload Int16')) WHERE ((eventdate >= '2013-07-01')) AND ((eventdate <= '2013-07-31')) AND ((islink <> 0)) AND ((counterid = 62)) AND ((isrefresh = 0)) AND ((isdownload = 0)) GROUP BY url ORDER BY count(*) DESC NULLS FIRST, url ASC NULLS LAST LIMIT 10 OFFSET 1000
